import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  username: async (data) => {
    if (typeof data.username !== "string") {
      throw new Error("Username is required");
    }
    return data.username;
  },
  password: async (data) => {
    // Wasp's auth handles password hashing and stores it in AuthIdentity.
    // The password field on the User model is a schema requirement.
    // If data.password is present, we return it, otherwise a placeholder.
    if (typeof data.password === "string") {
      return data.password;
    }
    return "dummy_password_hash_for_schema";
  },
  role: async (data) => {
    if (typeof data.role !== "string") {
      return "CUSTOMER";
    }
    const role = data.role.toUpperCase();
    if (role !== "CUSTOMER" && role !== "AGENT" && role !== "MANAGER") {
      throw new Error("Invalid role. Must be CUSTOMER, AGENT, or MANAGER");
    }
    return role;
  },
});

import { createProviderId, sanitizeAndSerializeProviderData, createUser } from "wasp/server/auth";

export const seedData = async (prisma: any) => {
  const usersToSeed = [
    { username: "manager", password: "password123", role: "MANAGER" },
    { username: "agent1", password: "password123", role: "AGENT" },
    { username: "agent2", password: "password123", role: "AGENT" },
    { username: "customer1", password: "password123", role: "CUSTOMER" },
  ];

  for (const user of usersToSeed) {
    const existing = await prisma.user.findUnique({
      where: { username: user.username },
    });

    if (!existing) {
      const providerId = createProviderId("username", user.username);
      const providerData = await sanitizeAndSerializeProviderData({
        hashedPassword: user.password,
      });
      const hashedPassword = JSON.parse(providerData).hashedPassword;
      await createUser(providerId, providerData, {
        username: user.username,
        password: hashedPassword || user.password,
        role: user.role,
      });
      console.log(`Seeded user: ${user.username} with role ${user.role}`);
    } else {
      console.log(`User already exists: ${user.username}`);
    }
  }
};

import { HttpError } from "wasp/server";
import type { GetTickets, GetAgents } from "wasp/server/operations";

export const getTickets: GetTickets<void, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  return context.entities.Ticket.findMany({
    include: {
      assignee: true,
      creator: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });
};

export const getAgents: GetAgents<void, any> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const agents = await context.entities.User.findMany({
    where: { role: "AGENT" },
    include: {
      ticketsAssigned: {
        where: {
          status: { not: "RESOLVED" },
        },
      },
    },
    orderBy: {
      id: "asc",
    },
  });

  return agents.map((agent: any) => ({
    id: agent.id,
    username: agent.username,
    role: agent.role,
    workload: agent.ticketsAssigned.length,
  }));
};

import { HttpError } from "wasp/server";
import type { CreateTicket, SimulateSlaBreach } from "wasp/server/operations";

export const createTicket: CreateTicket<
  { title: string; description: string; priority: "HIGH" | "MEDIUM" | "LOW" },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  // 1. Calculate SLA deadline
  const createdAt = new Date();
  let durationSeconds = 24 * 3600; // default LOW
  if (args.priority === "HIGH") {
    durationSeconds = 3600;
  } else if (args.priority === "MEDIUM") {
    durationSeconds = 14400;
  } else if (args.priority === "LOW") {
    durationSeconds = 86400;
  }
  const slaDeadline = new Date(createdAt.getTime() + durationSeconds * 1000);

  // 2. Automatic workload-based assignment
  const agents = await context.entities.User.findMany({
    where: { role: "AGENT" },
    include: {
      ticketsAssigned: {
        where: {
          status: { not: "RESOLVED" },
        },
      },
    },
    orderBy: {
      id: "asc",
    },
  });

  let chosenAgent = null;
  if (agents.length > 0) {
    chosenAgent = agents[0];
    for (let i = 1; i < agents.length; i++) {
      if (agents[i].ticketsAssigned.length < chosenAgent.ticketsAssigned.length) {
        chosenAgent = agents[i];
      }
    }
  }

  const assigneeId = chosenAgent ? chosenAgent.id : null;

  // 3. Create and return the ticket
  return context.entities.Ticket.create({
    data: {
      title: args.title,
      description: args.description,
      priority: args.priority,
      status: "OPEN",
      createdAt,
      slaDeadline,
      isEscalated: false,
      creatorId: context.user.id,
      assigneeId,
    },
    include: {
      assignee: true,
      creator: true,
    },
  });
};

export const simulateSlaBreach: SimulateSlaBreach<
  { ticketId: number },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  // 1. Find the ticket
  const ticket = await context.entities.Ticket.findUnique({
    where: { id: args.ticketId },
  });

  if (!ticket) {
    throw new HttpError(404, "Ticket not found");
  }

  // 2. Subtract exactly 2 hours from both createdAt and slaDeadline
  const newCreatedAt = new Date(ticket.createdAt.getTime() - 2 * 3600 * 1000);
  const newSlaDeadline = new Date(ticket.slaDeadline.getTime() - 2 * 3600 * 1000);

  let updatedTicket = await context.entities.Ticket.update({
    where: { id: args.ticketId },
    data: {
      createdAt: newCreatedAt,
      slaDeadline: newSlaDeadline,
    },
    include: {
      assignee: true,
      creator: true,
    },
  });

  // 3. Check if breached (slaDeadline is in past, status is not RESOLVED, and isEscalated is false)
  const isBreached =
    newSlaDeadline.getTime() < Date.now() &&
    updatedTicket.status !== "RESOLVED" &&
    !updatedTicket.isEscalated;

  if (isBreached) {
    // Reassign to manager with smallest ID
    const managers = await context.entities.User.findMany({
      where: { role: "MANAGER" },
      orderBy: { id: "asc" },
    });

    const managerId = managers.length > 0 ? managers[0].id : undefined;

    const updateData: any = {
      isEscalated: true,
    };
    if (managerId !== undefined) {
      updateData.assigneeId = managerId;
    }

    updatedTicket = await context.entities.Ticket.update({
      where: { id: args.ticketId },
      data: updateData,
      include: {
        assignee: true,
        creator: true,
      },
    });
  }

  return updatedTicket;
};

