                <p className="text-sm text-gray-500">Loading tickets...</p>
              ) : ticketsError ? (
                <p className="text-sm text-red-600">Error loading tickets</p>
              ) : tickets && tickets.length > 0 ? (
                <div className="space-y-4">
                  {tickets.map((ticket: any) => (
                    <div
                      key={ticket.id}
                      data-testid="ticket-item"
                      className="border border-gray-200 rounded-lg p-4 hover:shadow-sm transition"
                    >
                      <div className="flex justify-between items-start mb-2">
                        <div>
                          <h3 className="font-bold text-gray-900">{ticket.title}</h3>
                          <p className="text-xs text-gray-500">
                            Created by {ticket.creator?.username || "Unknown"}
                          </p>
                        </div>
                        <div className="flex space-x-2">
                          <span className="px-2 py-1 text-xs font-semibold rounded bg-gray-100 text-gray-800">
                            {ticket.priority}
                          </span>
                          <span
                            data-testid={`ticket-status-badge-${ticket.id}`}
                            className={`px-2 py-1 text-xs font-semibold rounded ${
                              ticket.isEscalated
                                ? "bg-red-100 text-red-800"
                                : ticket.status === "RESOLVED"
                                ? "bg-green-100 text-green-800"
                                : "bg-blue-100 text-blue-800"
                            }`}
                          >
                            {ticket.isEscalated ? "ESCALATED" : ticket.status}
                          </span>
                        </div>
                      </div>

                      <p className="text-sm text-gray-700 mb-4">{ticket.description}</p>

                      <div className="grid grid-cols-2 gap-2 text-xs text-gray-600 mb-4 border-t pt-3">
                        <div>
                          <span className="font-medium">Assignee:</span>{" "}
                          <span data-testid={`ticket-assignee-${ticket.id}`}>
                            {ticket.assignee ? ticket.assignee.username : "Unassigned"}
                          </span>
                        </div>
                        <div>
                          <span className="font-medium">Escalated:</span>{" "}
                          <span data-testid={`ticket-escalated-${ticket.id}`}>
                            {ticket.isEscalated ? "Yes" : "No"}
                          </span>
                        </div>
                        <div className="col-span-2">
                          <span className="font-medium">SLA Deadline:</span>{" "}
                          <span data-testid={`ticket-sla-deadline-${ticket.id}`}>
                            {new Date(ticket.slaDeadline).toISOString()}
                          </span>
                        </div>
                      </div>

                      <button
                        data-testid={`simulate-breach-${ticket.id}`}
                        onClick={() => handleSimulateBreach(ticket.id)}
                        className="text-xs bg-amber-500 hover:bg-amber-600 text-white font-medium py-1 px-3 rounded transition"
                      >
                        Simulate SLA Breach
                      </button>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-sm text-gray-500">No support tickets found.</p>
              )}
            </section>
          </div>
        </div>
      </div>
    </div>
  );
}

import { HttpError } from "wasp/server";
import type { CreateTicket, SimulateSlaBreach } from "wasp/server/operations";

export const createTicket: CreateTicket<
  { title: string; description: string; priority: "HIGH" | "MEDIUM" | "LOW" },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  // 1. Calculate SLA deadline
  const createdAt = new Date();
  let durationSeconds = 24 * 3600; // default LOW
  if (args.priority === "HIGH") {
    durationSeconds = 3600;
  } else if (args.priority === "MEDIUM") {
    durationSeconds = 14400;
  } else if (args.priority === "LOW") {
    durationSeconds = 86400;
  }
  const slaDeadline = new Date(createdAt.getTime() + durationSeconds * 1000);

  // 2. Automatic workload-based assignment
  const agents = await context.entities.User.findMany({
    where: { role: "AGENT" },
    include: {
      ticketsAssigned: {
        where: {
          status: { not: "RESOLVED" },
        },
      },
    },
    orderBy: {
      id: "asc",
    },
  });

  let chosenAgent: any = null;
  if (agents.length > 0) {
    chosenAgent = agents[0];
    for (let i = 1; i < agents.length; i++) {
      if (agents[i].ticketsAssigned.length < chosenAgent.ticketsAssigned.length) {
        chosenAgent = agents[i];
      }
    }
  }

  const assigneeId = chosenAgent ? chosenAgent.id : null;

  // 3. Create and return the ticket
  return context.entities.Ticket.create({
    data: {
      title: args.title,
      description: args.description,
      priority: args.priority,
      status: "OPEN",
      createdAt,
      slaDeadline,
      isEscalated: false,
      creatorId: context.user.id,
      assigneeId,
    },
    include: {
      assignee: true,
      creator: true,
    },
  });
};

export const simulateSlaBreach: SimulateSlaBreach<
  { ticketId: number },
  any
> = async (args, context) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  // 1. Find the ticket
  const ticket = await context.entities.Ticket.findUnique({
    where: { id: args.ticketId },
  });

  if (!ticket) {
    throw new HttpError(404, "Ticket not found");
  }

  // 2. Subtract exactly 2 hours from both createdAt and slaDeadline
  const newCreatedAt = new Date(ticket.createdAt.getTime() - 2 * 3600 * 1000);
  const newSlaDeadline = new Date(ticket.slaDeadline.getTime() - 2 * 3600 * 1000);

  let updatedTicket = await context.entities.Ticket.update({
    where: { id: args.ticketId },
    data: {
      createdAt: newCreatedAt,
      slaDeadline: newSlaDeadline,
    },
    include: {
      assignee: true,
      creator: true,
    },
  });

  // 3. Check if breached (slaDeadline is in past, status is not RESOLVED, and isEscalated is false)
  const isBreached =
    newSlaDeadline.getTime() < Date.now() &&
    updatedTicket.status !== "RESOLVED" &&
    !updatedTicket.isEscalated;

  if (isBreached) {
    // Reassign to manager with smallest ID
    const managers = await context.entities.User.findMany({
      where: { role: "MANAGER" },
      orderBy: { id: "asc" },
    });

    const managerId = managers.length > 0 ? managers[0].id : undefined;

    const updateData: any = {
      isEscalated: true,
    };
    if (managerId !== undefined) {
      updateData.assigneeId = managerId;
    }

    updatedTicket = await context.entities.Ticket.update({
      where: { id: args.ticketId },
      data: updateData,
      include: {
        assignee: true,
        creator: true,
      },
    });
  }

  return updatedTicket;
};
